import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import tools.jackson.databind.node.ObjectNode;

/** cp04: an owner's email, when provided, must be unique across all owners (409). */
@Tag("cp04")
class Cp04Tests extends AcceptanceBase {

	@Test
	void coreRejectsDuplicateEmail() throws Exception {
		ObjectNode a = ownerNode();
		a.put("email", uniqueEmail());
		createOwnerOk(a);
		ObjectNode b = ownerNode(); // distinct name/address/city/telephone
		b.put("email", a.get("email").asText());
		createOwner(b).andExpect(status().isConflict());
	}

	@Test
	void functionalityAllowsDistinctEmails() throws Exception {
		ObjectNode a = ownerNode();
		a.put("email", uniqueEmail());
		createOwnerOk(a);
		ObjectNode b = ownerNode();
		b.put("email", uniqueEmail());
		createOwner(b).andExpect(status().is2xxSuccessful());
	}

	@Test
	void storesAndReturnsEmail() throws Exception {
		ObjectNode a = ownerNode();
		String email = uniqueEmail();
		a.put("email", email);
		int id = createOwnerOk(a);
		getOwner(id).andExpect(status().is2xxSuccessful())
				.andExpect(jsonPath("$.email").value(email));
	}

	@Test
	void functionalityAllowsMissingEmail() throws Exception {
		createOwnerOk(ownerNode()); // no email
		createOwner(ownerNode()).andExpect(status().is2xxSuccessful());
	}
}

